window.HOEREN_TESTS[14] = {"id":"kino-theater-und-konzert","name":"Kino, Theater und Konzert","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung, liebe Kinobesucher: Wegen technischer Probleme verschiebt sich der Film ‚Sommerträume‘ um 30 Minuten. Statt 20 Uhr startet er erst um 20 Uhr 30. Nicht erst morgen, heute um 20 Uhr 30. Für die Wartezeit bietet die Kino-Bar Getränke zum halben Preis. Falls Sie nicht warten können, geben wir Ihnen das Geld zurück. Danke!","gender":"f","q":"Wann beginnt der Film?","opts":["Um 20 Uhr 30.","Um 20 Uhr wie geplant.","Erst morgen."],"correct":0},{"transcript":"Hallo Schatz, hier ist Tom. Die Theaterkarten für Samstag — du hast Recht, das Stück ist abgesagt. Aber gleichzeitig gibt es eine andere Vorstellung im selben Theater — ‚Faust‘ um 19 Uhr 30. Soll ich die Karten auf Faust umtauschen? Ich hole dich ab, du musst nicht allein nach Hause. Sag Bescheid bis heute Abend. Danke!","gender":"m","q":"Was möchte Tom wissen?","opts":["Ob sie die Karten zurückgeben.","Ob sie das andere Stück sehen wollen.","Ob sie selbst nach Hause kommt."],"correct":1},{"transcript":"Liebe Konzertbesucher, das Konzert beginnt pünktlich um 20 Uhr. Bitte schalten Sie Ihre Handys aus, nicht nur lautlos — wirklich aus, weil das Signal die Mikrofone stört. Fotos und Videos sind in der Pause erlaubt, während des Konzerts streng verboten. Wir wünschen Ihnen einen schönen Abend. Danke!","gender":"f","q":"Wann sind Fotos erlaubt?","opts":["Immer während des Konzerts.","Gar nicht.","Nur in der Pause."],"correct":2},{"transcript":"Anrufbeantworter des Stadttheaters. Wir sind heute, Montag, geschlossen. Dienstag bis Sonntag sind wir von 10 bis 19 Uhr erreichbar. Für Karten-Buchungen besuchen Sie unsere Webseite — das ist 24 Stunden möglich. Bei dringenden Fragen schreiben Sie eine E-Mail. Wir freuen uns auf Ihren Besuch von Dienstag bis Sonntag! Bis morgen!","gender":"m","q":"Wann hat das Theater geschlossen?","opts":["Dienstag.","Montag.","Sonntag."],"correct":1},{"transcript":"Hallo, hier ist das Filmfestival München. Sie haben Karten für die Eröffnung am Donnerstag bestellt. Bitte denken Sie an Ihren Ausweis — ohne Ausweis kommen Sie nicht rein, das ist Vorschrift. Karten haben Sie ja online auf dem Handy. Treffpunkt ist 18 Uhr 30 am Haupteingang. Schönen Abend!","gender":"f","q":"Was müssen die Karteninhaber mitbringen?","opts":["Karte und Ausweis.","Nur die Karte auf dem Handy.","Karte und Bargeld."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Anna und Markus. Sie planen einen Kulturmonat — eine andere Aktivität pro Woche. Sie hören den Text einmal. Was machen sie in welcher Woche? Wählen Sie für jede Woche einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Im Kulturmonat machen wir jede Woche etwas anderes."},{"speaker":"Markus","gender":"m","text":"Fünf Wochen hintereinander finde ich stark. Daraus wird ein richtig schöner Plan."},{"speaker":"Anna","gender":"f","text":"Ein Kino-Besuch ist in Woche 1 dran. Der neue Film läuft am Abend."},{"speaker":"Markus","gender":"m","text":"Kino mag ich immer. Wollen wir auch eine Lesung im Buchladen besuchen?"},{"speaker":"Anna","gender":"f","text":"Nein. Eine Lesung machen wir nicht. Dafür sind wir beide zu unruhig."},{"speaker":"Markus","gender":"m","text":"Eine Theater-Vorstellung sehen wir in Woche 2. Sie beginnt um sieben."},{"speaker":"Anna","gender":"f","text":"Wir nehmen die Plätze in der Mitte. Von dort sehen wir die Bühne am besten."},{"speaker":"Markus","gender":"m","text":"Danach soll es musikalisch werden. Wir wollen einen ruhigen Abend."},{"speaker":"Anna","gender":"f","text":"Ein Klassik-Konzert hören wir in Woche 3. Geigen und Klavier stehen auf dem Zettel."},{"speaker":"Markus","gender":"m","text":"Klassik passt gut in den ruhigen Saal. Ich freue mich schon darauf."},{"speaker":"Anna","gender":"f","text":"Eine Kunstausstellung mit großen und bunten Bildern sehen wir in Woche 4."},{"speaker":"Markus","gender":"m","text":"Die Ausstellung im Museum kenne ich schon. Bleibt die teure Oper auch draußen?"},{"speaker":"Anna","gender":"f","text":"Nein. Eine Oper besuchen wir nicht. Die Karten sind uns einfach zu teuer."},{"speaker":"Markus","gender":"m","text":"Was planen wir dann ganz zum Schluss?"},{"speaker":"Anna","gender":"f","text":"Ein Filmfestival läuft in Woche 5. Wir sehen drei kurze Filme an einem Abend."},{"speaker":"Markus","gender":"m","text":"Einverstanden. Ein Filmfestival ist anders als normales Kino."}],"options":[{"letter":"a","text":"Lesung im Buchladen"},{"letter":"b","text":"Filmfestival"},{"letter":"c","text":"Kino-Besuch"},{"letter":"d","text":"Tanz-Aufführung"},{"letter":"e","text":"Open-Air-Konzert"},{"letter":"f","text":"Kunstausstellung"},{"letter":"g","text":"Oper-Besuch"},{"letter":"h","text":"Theater-Vorstellung"},{"letter":"i","text":"Klassik-Konzert"}],"items":[{"person":"Woche 1","correct":"c"},{"person":"Woche 2","correct":"h"},{"person":"Woche 3","correct":"i"},{"person":"Woche 4","correct":"f"},{"person":"Woche 5","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Eine Karte für den Film ‚Sommerträume‘."},{"speaker":"Verkäuferin","gender":"f","text":"Welche Vorstellung? 18 Uhr, 20 Uhr 30 oder 22 Uhr 45? Spät wird es auch."},{"speaker":"Kunde","gender":"m","text":"20 Uhr 30 wäre gut. Nicht 18 Uhr, zu früh."},{"speaker":"Verkäuferin","gender":"f","text":"Reihe? Vorne, Mitte oder hinten? Hinten ist fast voll."},{"speaker":"Kunde","gender":"m","text":"Mitte, bitte. Ist noch etwas frei?"},{"speaker":"Verkäuferin","gender":"f","text":"Ja, Mitte ist frei. Viel Spaß beim Film um 20 Uhr 30!"}],"q":"Wann beginnt die Vorstellung?","opts":["Um 18 Uhr.","Um 20 Uhr 30.","Um 22 Uhr 45."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Welches Buch möchtest du lesen?"},{"speaker":"Mann","gender":"m","text":"Etwas Spannendes. Krimi vielleicht?"},{"speaker":"Frau","gender":"f","text":"Hier — ‚Der schwarze Schatten‘. Sehr gut bewertet."},{"speaker":"Mann","gender":"m","text":"Hmm, mir ist Krimi heute zu dunkel. Beide nehmen wäre zu viel."},{"speaker":"Frau","gender":"f","text":"‚Sommer in Paris‘ — eine leichte Komödie. Perfekt für den Urlaub."},{"speaker":"Mann","gender":"m","text":"Genau das brauche ich. Das nehme ich. Danke!"}],"q":"Was nimmt der Mann?","opts":["Die Komödie.","Den Krimi.","Beide Bücher."],"correct":0},{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Konzerthaus, guten Abend."},{"speaker":"Anrufer","gender":"m","text":"Hallo, ich möchte 2 Karten für das Klassikkonzert am Freitag."},{"speaker":"Mitarbeiterin","gender":"f","text":"Welcher Bereich? Parkett, erster Rang oder zweiter Rang?"},{"speaker":"Anrufer","gender":"m","text":"Erster Rang, falls noch frei."},{"speaker":"Mitarbeiterin","gender":"f","text":"Frei ist da nichts mehr. Aber Parkett oder zweiter Rang gibt es noch, beide gut."},{"speaker":"Anrufer","gender":"m","text":"Parkett dann, näher dran. Danke schön!"}],"q":"Welche Karten kauft der Anrufer?","opts":["Erster Rang.","Parkett-Karten.","Zweiter Rang."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Was möchtest du heute machen?"},{"speaker":"Sohn","gender":"m","text":"Ins Kino gehen!"},{"speaker":"Vater","gender":"m","text":"Im Kino läuft kein Kinderfilm gerade, nur Theater für Erwachsene. Aber das neue Museum hat eine Kinder-Ausstellung."},{"speaker":"Sohn","gender":"m","text":"Museum klingt langweilig. Kino wäre besser, oder?"},{"speaker":"Vater","gender":"m","text":"Es ist eine interaktive Ausstellung — du kannst alles anfassen und mitmachen, versprochen."},{"speaker":"Sohn","gender":"m","text":"Okay, dann Museum! Das wird toll, Papa!"}],"q":"Wohin gehen sie?","opts":["Ins Kino.","Ins Theater.","Ins Museum."],"correct":2},{"lines":[{"speaker":"Anrufer","gender":"m","text":"Ich habe Karten für das Konzert morgen, aber ich kann nicht kommen."},{"speaker":"Mitarbeiterin","gender":"f","text":"Möchten Sie das Geld zurück oder Karten für eine andere Vorstellung?"},{"speaker":"Anrufer","gender":"m","text":"Geld zurück wäre besser. Ich weiß nicht, wann ich Zeit habe."},{"speaker":"Mitarbeiterin","gender":"f","text":"Wir können das Geld zurückgeben, abzüglich 5 Euro Bearbeitungsgebühr pro Karte. So sind die Regeln."}],"q":"Was bekommt der Anrufer?","opts":["Karten für andere Vorstellung.","Volles Geld zurück.","Geld zurück, abzüglich Gebühr."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Stein, einer Theaterschauspielerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Stein, Sie sind seit 15 Jahren Schauspielerin am Stadttheater. Was hat Sie zu diesem Beruf geführt?"},{"speaker":"Stein","gender":"f","text":"Eigentlich wollte ich Tänzerin werden. Aber mit 16 Jahren habe ich bei einer Schultheater-Aufführung mitgemacht und das war wie eine Offenbarung. Tanzen ist schön, aber Schauspielen — das ist mein Herz."},{"speaker":"Reporter","gender":"m","text":"Wie sehen Ihre Arbeitstage aus?"},{"speaker":"Stein","gender":"f","text":"Sehr unterschiedlich, während wir ein neues Stück proben, sind wir 6 bis 8 Stunden am Tag im Theater. In der Spielzeit dann abends Vorstellungen, manchmal auch nachmittags. Ich habe wenige freie Wochenenden."},{"speaker":"Reporter","gender":"m","text":"Welche Rollen spielen Sie am liebsten?"},{"speaker":"Stein","gender":"f","text":"Komische Rollen liebe ich am meisten. Das Publikum zum Lachen zu bringen, ist die schönste Belohnung. Tragische Rollen sind anstrengender, weil man dafür viel emotionale Energie braucht."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"Stein","gender":"f","text":"Kritik. Wenn jemand eine schlechte Kritik in der Zeitung schreibt, tut das weh. Aber man muss lernen, das nicht persönlich zu nehmen. Heute bin ich da viel ruhiger als am Anfang meiner Karriere."},{"speaker":"Reporter","gender":"m","text":"Gehen Sie selbst ins Theater?"},{"speaker":"Stein","gender":"f","text":"Sehr selten. Wenn ich abends nicht spiele, will ich nicht wieder im Theater sitzen. Ich gehe lieber ins Kino — das ist eine andere Welt, eine echte Auszeit."}],"items":[{"q":"Frau Stein wollte als Kind Schauspielerin werden.","correct":"nein"},{"q":"Sie hat oft am Wochenende frei.","correct":"nein"},{"q":"Tragische Rollen sind ihre Lieblingsrollen.","correct":"nein"},{"q":"Schlechte Kritik nimmt sie heute weniger persönlich.","correct":"ja"},{"q":"In ihrer Freizeit geht sie oft ins Theater.","correct":"nein"}]}]};
